returns trigger
language plpgsql
security invoker
set search_path = pg_catalog
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'The document creator cannot be changed'
      using errcode = '42501';
  end if;

  if new.deleted_at is distinct from old.deleted_at
     and old.created_by is distinct from auth.uid() then
    raise exception 'Only the document creator may change its deletion status'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

