create function public.enforce_document_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  caller_id uuid := auth.uid();
  old_team_editor boolean;
  new_team_editor boolean;
begin
  if current_user = 'service_role'
     or auth.role() = 'service_role' then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'Document ownership cannot be changed'
      using errcode = '42501';
  end if;

  if new.deleted_at is distinct from old.deleted_at
     and old.created_by is distinct from caller_id then
    raise exception 'Only the creator can delete a document'
      using errcode = '42501';
  end if;

  select exists (
    select 1
    from public.team_members as m
    where m.team_id = old.team_id
      and m.user_id = caller_id
      and m.role = 'editor'
  ) into old_team_editor;

  select exists (
    select 1
    from public.team_members as m
    where m.team_id = new.team_id
      and m.user_id = caller_id
      and m.role = 'editor'
  ) into new_team_editor;

  if old_team_editor and new_team_editor then
    return new;
  end if;

  if old.created_by = caller_id
     and old.deleted_at is null
     and new.deleted_at is not null
     and row(new.id, new.team_id, new.title, new.created_by)
         is not distinct from
         row(old.id, old.team_id, old.title, old.created_by) then
    return new;
  end if;

  raise exception 'Editing requires editor membership in both teams'
    using errcode = '42501';
end;
$$;

