returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if auth.role() is distinct from 'authenticated' then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'Document creator cannot be changed'
      using errcode = '42501';
  end if;

  if old.deleted_at is not null then
    raise exception 'Deleted documents cannot be changed'
      using errcode = '42501';
  end if;

  if new.deleted_at is distinct from old.deleted_at
     and old.created_by is distinct from auth.uid() then
    raise exception 'Only the document creator can delete it'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

