grant select, update on table public.employees to authenticated;
grant all on table public.employees to service_role;

grant usage on schema public to authenticated, service_role;

create function public.employee_is_hr()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.employees as e
    where e.user_id = auth.uid()
      and e.department = 'HR'
  );
$$;

revoke all on function public.employee_is_hr()
  from public, anon, authenticated;
grant execute on function public.employee_is_hr()
  to authenticated, service_role;

create policy employees_read_self_or_hr
on public.employees
for select
to authenticated
using (
  user_id = (select auth.uid())
  or (select public.employee_is_hr())
);

create policy employees_update_hr_only
on public.employees
for update
to authenticated
using ((select public.employee_is_hr()))
with check (true);

create function public.employee_directory_rows()
returns table (
  id bigint,
  full_name text,
  department text
)
language sql
stable
security definer
set search_path = ''
as $$
  select e.id, e.full_name, e.department
  from public.employees as e
  where auth.role() = 'service_role'
     or exists (
       select 1
       from public.employees as caller
       where caller.user_id = auth.uid()
     );
$$;

revoke all on function public.employee_directory_rows()
  from public, anon, authenticated;
grant execute on function public.employee_directory_rows()
  to authenticated, service_role;

create view public.employee_directory
with (security_invoker = true, security_barrier = true)
as
select id, full_name, department
from public.employee_directory_rows();

