create function public.decide_expense(
  p_expense_id bigint,
  p_approve boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller uuid := auth.uid();
  v_service boolean := coalesce(auth.role() = 'service_role', false);
begin
  if p_approve is null then
    raise exception 'Approval decision must not be null';
  end if;

  if not v_service and (
    auth.role() is distinct from 'authenticated'
    or v_caller is null
  ) then
    raise exception 'Not authorized to decide expenses';
  end if;

  update public.expenses as expense
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = case when v_service then null else v_caller end
  where expense.id = p_expense_id
    and expense.status = 'pending'
    and (
      v_service
      or (
        expense.submitted_by <> v_caller
        and exists (
          select 1
          from public.department_members as membership
          where membership.department_id = expense.department_id
            and membership.user_id = v_caller
            and membership.is_manager
        )
      )
    );

  if not found then
    raise exception 'Expense cannot be decided';
  end if;
end;
$$;

