create function public.decide_expense(
  p_expense_id bigint,
  p_approve boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_is_service boolean := coalesce(auth.role() = 'service_role', false);
begin
  if p_approve is null then
    raise exception 'A decision is required';
  end if;

  if not v_is_service
     and (auth.role() is distinct from 'authenticated' or v_user_id is null)
  then
    raise exception 'Expense decision not permitted';
  end if;

  update public.expenses as e
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = case when v_is_service then null else v_user_id end
  where e.id = p_expense_id
    and e.status = 'pending'
    and (
      v_is_service
      or (
        e.submitted_by <> v_user_id
        and exists (
          select 1
          from public.department_members as dm
          where dm.department_id = e.department_id
            and dm.user_id = v_user_id
            and dm.is_manager
        )
      )
    );

  if not found then
    raise exception 'Expense decision not permitted or expense is not pending';
  end if;
end;
$$;

revoke all privileges on function public.decide_expense(bigint, boolean)
from public, anon, authenticated;

grant execute on function public.decide_expense(bigint, boolean)
to authenticated, service_role;
