create function public.soft_delete_document()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'UPDATE' then
    if new.deleted_at is not distinct from old.deleted_at then
      return new;
    end if;

    if old.deleted_at is not null
       or new.deleted_at is null
       or old.created_by is distinct from auth.uid()
       or new.created_by is distinct from old.created_by then
      raise exception 'Invalid document deletion'
        using errcode = '42501';
    end if;

    if pg_trigger_depth() > 1 then
      return new;
    end if;

    if not exists (
      select 1
      from public.team_members as m
      where m.team_id = old.team_id
        and m.user_id = auth.uid()
        and m.role = 'editor'
    ) or not exists (
      select 1
      from public.team_members as m
      where m.team_id = new.team_id
        and m.user_id = auth.uid()
        and m.role = 'editor'
    ) then
      raise exception 'Editor membership required'
        using errcode = '42501';
    end if;

    update public.documents
    set id = new.id,
        team_id = new.team_id,
        title = new.title,
        deleted_at = new.deleted_at
    where id = old.id;

    return null;
  end if;

  if old.deleted_at is not null
     or old.created_by is distinct from auth.uid()
     or not exists (
       select 1
       from public.team_members as m
       where m.team_id = old.team_id
         and m.user_id = auth.uid()
     ) then
    raise exception 'Only the document creator can delete the document'
      using errcode = '42501';
  end if;

  update public.documents
  set deleted_at = pg_catalog.clock_timestamp()
  where id = old.id;

  return null;
end;
$$;

