create function public.guard_document_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if auth.role() is distinct from 'authenticated' then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'Document authorship cannot be changed'
      using errcode = '42501';
  end if;

  if new.deleted_at is distinct from old.deleted_at
     and old.created_by is distinct from auth.uid() then
    raise exception 'Only the creator can delete a document'
      using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.team_members as membership
    where membership.team_id = old.team_id
      and membership.user_id = auth.uid()
      and membership.role = 'editor'
  ) or not exists (
    select 1
    from public.team_members as membership
    where membership.team_id = new.team_id
      and membership.user_id = auth.uid()
      and membership.role = 'editor'
  ) then
    if old.created_by is distinct from auth.uid()
       or old.deleted_at is not null
       or new.deleted_at is null
       or row(new.id, new.team_id, new.title, new.created_by)
          is distinct from
          row(old.id, old.team_id, old.title, old.created_by) then
      raise exception 'Only editors can edit documents; creators may only soft-delete'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;

