  target_org_id bigint,
  admin_required boolean default false
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members as m
    where m.org_id = target_org_id
      and m.user_id = (select auth.uid())
      and (not admin_required or m.role = 'admin')
  );
