  (select public.app_account_is_active())
  and (
    owner_id = (select auth.uid())
    or exists (
      select 1
      from public.file_shares as s
      where s.file_id = files.id
        and s.shared_with = (select auth.uid())
        and (s.expires_at is null or s.expires_at > now())
    )
  )
);

