create function public.enforce_org_membership_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_id bigint;
  v_actor uuid;
  v_actor_role text;
  v_creator uuid;
begin
  if auth.role() = 'service_role' then
    if TG_OP = 'DELETE' then
      return OLD;
    end if;
    return NEW;
  end if;

  v_actor := auth.uid();

  if v_actor is null or auth.role() is distinct from 'authenticated' then
    raise exception 'Authentication required'
      using errcode = '42501';
  end if;

  if TG_OP = 'UPDATE' then
    if NEW.org_id is distinct from OLD.org_id
       or NEW.user_id is distinct from OLD.user_id then
      raise exception 'Membership identity cannot be changed'
        using errcode = '42501';
    end if;
  end if;

  if TG_OP = 'DELETE' then
    v_org_id := OLD.org_id;
  else
    v_org_id := NEW.org_id;
  end if;

  select o.created_by
    into v_creator
  from public.orgs as o
  where o.id = v_org_id
  for update;

  if not found then
    raise exception 'Organization does not exist'
      using errcode = '23503';
  end if;

  select m.role
    into v_actor_role
  from public.org_members as m
  where m.org_id = v_org_id
    and m.user_id = v_actor;

  if TG_OP = 'INSERT' then
    if NEW.user_id = v_actor then
      if NEW.role = 'owner'
         and v_creator = v_actor
         and not exists (
           select 1
           from public.org_members as m
           where m.org_id = v_org_id
         ) then
        return NEW;
      end if;
    elsif v_actor_role = 'owner'
       or (v_actor_role = 'admin' and NEW.role = 'member') then
      return NEW;
    end if;

    raise exception 'Membership insertion is not permitted'
      using errcode = '42501';

  elsif TG_OP = 'UPDATE' then
    if OLD.user_id <> v_actor and v_actor_role = 'owner' then
      return NEW;
    end if;

    raise exception 'Membership update is not permitted'
      using errcode = '42501';

  elsif TG_OP = 'DELETE' then
    if OLD.user_id = v_actor then
      if OLD.role = 'owner'
         and not exists (
           select 1
           from public.org_members as m
           where m.org_id = v_org_id
             and m.role = 'owner'
             and m.user_id <> OLD.user_id
         ) then
        raise exception 'The only owner cannot leave'
          using errcode = '42501';
      end if;

      return OLD;
    end if;

    if v_actor_role = 'owner'
       or (v_actor_role = 'admin' and OLD.role = 'member') then
      return OLD;
    end if;

    raise exception 'Membership deletion is not permitted'
      using errcode = '42501';
  end if;

  raise exception 'Unsupported operation'
    using errcode = '42501';
end;
$$;

