create function public.rls_guard_org_members()
returns trigger
language plpgsql
security definer
set search_path = ''
set row_security = off
as $$
declare
  v_uid uuid;
  v_org_id bigint;
  v_creator uuid;
  v_actor_role text;
begin
  if auth.role() is distinct from 'authenticated' then
    if TG_OP = 'DELETE' then
      return OLD;
    end if;
    return NEW;
  end if;

  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if TG_OP = 'DELETE' then
    v_org_id := OLD.org_id;
  else
    v_org_id := NEW.org_id;
  end if;

  if TG_OP = 'UPDATE' then
    if NEW.org_id is distinct from OLD.org_id
       or NEW.user_id is distinct from OLD.user_id then
      raise exception 'Membership identity cannot be changed'
        using errcode = '42501';
    end if;
  end if;

  select o.created_by
  into v_creator
  from public.orgs as o
  where o.id = v_org_id
  for update;

  if not found then
    raise exception 'Organization unavailable' using errcode = '42501';
  end if;

  select m.role
  into v_actor_role
  from public.org_members as m
  where m.org_id = v_org_id
    and m.user_id = v_uid;

  if TG_OP = 'INSERT' then
    if NEW.user_id = v_uid then
      if NEW.role is distinct from 'owner'
         or v_creator is distinct from v_uid
         or exists (
           select 1
           from public.org_members as m
           where m.org_id = v_org_id
         ) then
        raise exception 'Self-enrollment is not permitted'
          using errcode = '42501';
      end if;
    elsif not coalesce(
      v_actor_role = 'owner'
      or (v_actor_role = 'admin' and NEW.role = 'member'),
      false
    ) then
      raise exception 'Membership insertion is not permitted'
        using errcode = '42501';
    end if;

    return NEW;
  end if;

  if TG_OP = 'UPDATE' then
    if OLD.user_id = v_uid
       or v_actor_role is distinct from 'owner' then
      raise exception 'Role change is not permitted'
        using errcode = '42501';
    end if;

    return NEW;
  end if;

  if OLD.user_id = v_uid then
    if OLD.role = 'owner'
       and not exists (
         select 1
         from public.org_members as m
         where m.org_id = v_org_id
           and m.role = 'owner'
           and m.user_id <> v_uid
       ) then
      raise exception 'The only owner cannot leave'
        using errcode = '42501';
    end if;
  elsif not coalesce(
    v_actor_role = 'owner'
    or (v_actor_role = 'admin' and OLD.role = 'member'),
    false
  ) then
    raise exception 'Membership deletion is not permitted'
      using errcode = '42501';
  end if;

  return OLD;
end;
$$;

