      using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' then
    if new.org_id is distinct from old.org_id
       or new.user_id is distinct from old.user_id then
      raise exception 'Membership identity cannot be changed'
        using errcode = '42501';
    end if;
  end if;

  if tg_op = 'DELETE' then
    v_org_id := old.org_id;
  else
    v_org_id := new.org_id;
  end if;

  select o.created_by
    into v_creator
  from public.orgs as o
  where o.id = v_org_id
  for update;

  if not found then
    raise exception 'Organization does not exist'
      using errcode = '23503';
  end if;

  select m.role
    into v_actor_role
  from public.org_members as m
  where m.org_id = v_org_id
    and m.user_id = v_uid;

  if tg_op = 'INSERT' then
    if new.user_id = v_uid then
      if new.role = 'owner'
         and v_creator = v_uid
         and not exists (
           select 1
           from public.org_members as m
           where m.org_id = v_org_id
