     and (
       NEW.org_id is distinct from OLD.org_id
       or NEW.user_id is distinct from OLD.user_id
     )
  then
    raise exception 'Membership identifiers cannot be changed'
      using errcode = '42501';
  end if;

  perform 1
  from public.orgs as o
  where o.id = v_org_id
  for update;

  if not found then
    raise exception 'Organization not found'
      using errcode = '42501';
  end if;

  select m.role
  into v_actor_role
  from public.org_members as m
  where m.org_id = v_org_id
    and m.user_id = v_uid;

  if TG_OP = 'INSERT' then
    if NEW.user_id = v_uid then
      if NEW.role = 'owner'
         and exists (
           select 1
           from public.orgs as o
           where o.id = v_org_id
             and o.created_by = v_uid
         )
         and not exists (
           select 1
           from public.org_members as m
           where m.org_id = v_org_id
         )
      then
        return NEW;
      end if;

      raise exception 'Self-enrollment is not permitted'
        using errcode = '42501';
    end if;

    if v_actor_role = 'owner'
       or (v_actor_role = 'admin' and NEW.role = 'member')
    then
      return NEW;
    end if;

    raise exception 'Insufficient permission to add this membership'
      using errcode = '42501';

  elsif TG_OP = 'UPDATE' then
    if OLD.user_id = v_uid then
      raise exception 'Users cannot change their own role'
        using errcode = '42501';
    end if;

    if v_actor_role = 'owner' then
      return NEW;
    end if;

    raise exception 'Only owners can change membership roles'
      using errcode = '42501';

