     or auth.uid() is null then
    raise exception 'Invoice updates require authentication'
      using errcode = '42501';
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'Invoice creator cannot be changed'
      using errcode = '42501';
  end if;

  if new.customer is distinct from old.customer
     or new.amount is distinct from old.amount then
    if old.status <> 'draft'
       or old.created_by is distinct from auth.uid() then
      raise exception 'Only the creator may edit customer or amount on a draft'
        using errcode = '42501';
    end if;
  end if;

  if new.status is distinct from old.status then
    if old.status = 'draft'
       and new.status = 'sent'
       and old.created_by = auth.uid() then
      return new;
    end if;

    if old.status = 'sent'
       and new.status in ('paid', 'void')
       and public.is_finance_staff() then
      return new;
    end if;

    raise exception 'Invoice status transition is not permitted'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

