to authenticated
using (
  owner_id = (select auth.uid())
  or (
    not is_private
    and exists (
      select 1
      from public.delegations as d
      where d.grantor_id = events.owner_id
        and d.delegate_id = (select auth.uid())
        and d.can_edit
        and (d.expires_at is null or d.expires_at > now())
    )
  )
)
with check (
  owner_id = (select auth.uid())
  or (
    not is_private
    and exists (
      select 1
      from public.delegations as d
      where d.grantor_id = events.owner_id
        and d.delegate_id = (select auth.uid())
        and d.can_edit
        and (d.expires_at is null or d.expires_at > now())
    )
  )
);

create policy events_delete
on public.events
for delete
to authenticated
using (
  owner_id = (select auth.uid())
  or (
    not is_private
    and exists (
      select 1
      from public.delegations as d
      where d.grantor_id = events.owner_id
        and d.delegate_id = (select auth.uid())
        and d.can_edit
        and (d.expires_at is null or d.expires_at > now())
    )
  )
);

create function public.visible_busy_slots()
returns table (
  owner_id uuid,
  starts_at timestamptz,
  ends_at timestamptz
)
language sql
stable
security definer
set search_path = ''
set row_security = off
as $$
  select e.owner_id, e.starts_at, e.ends_at
  from public.events as e
  where (select auth.role()) = 'service_role'
     or (
       (select auth.role()) = 'authenticated'
       and (
         e.owner_id = (select auth.uid())
         or exists (
           select 1
           from public.delegations as d
           where d.grantor_id = e.owner_id
             and d.delegate_id = (select auth.uid())
             and (
               d.expires_at is null
               or d.expires_at > pg_catalog.now()
             )
         )
       )
     );
$$;

revoke all on function public.visible_busy_slots()
from public, anon, authenticated;

grant execute on function public.visible_busy_slots()
to authenticated, service_role;

create view public.busy_slots
with (security_invoker = true, security_barrier = true)
as
select owner_id, starts_at, ends_at
from public.visible_busy_slots();

revoke all on table public.busy_slots
from public, anon, authenticated;

grant select on table public.busy_slots
to authenticated, service_role;
